    const w = 2.2 + 8.5 * Math.exp(-(((t - 0.09) / 0.075) ** 2)) + 10.5 * Math.exp(-(((t - 0.43) / 0.2) ** 2)) + 3.2 * (1 - t) + 2.5 * (1 - t * t);
