      const ua = T[o + u], va = T[o + v], ub = T[o + 3 + u], vb = T[o + 3 + v], uc = T[o + 6 + u], vc = T[o + 6 + v];
      const e0 = (ub - ua) * (pv - va) - (vb - va) * (pu - ua);
      const e1 = (uc - ub) * (pv - vb) - (vc - vb) * (pu - ub);
      const e2 = (ua - uc) * (pv - vc) - (va - vc) * (pu - uc);
