const view = $('#view'), glc = $('#gl'), ovc = $('#overlay'), octx = ovc.getContext('2d');
const renderer = new THREE.WebGLRenderer({ canvas: glc, antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setClearColor(0x000000, 0);
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(36, 1, 0.01, 500);
const grid = new THREE.GridHelper(14, 28, 0x59616b, 0x30363d);
grid.position.y = -1.02; grid.material.transparent = true; grid.material.opacity = 0.75; scene.add(grid);
let needsRender = true; const req = () => { needsRender = true; };

const cam = { target: new V3(0, 0, 0), r: 7, th: 0.35, ph: 1.2 };
function updateCam() {
  const t = cam.target;
  camera.position.set(t.x + cam.r * Math.sin(cam.ph) * Math.sin(cam.th), t.y + cam.r * Math.cos(cam.ph), t.z + cam.r * Math.sin(cam.ph) * Math.cos(cam.th));
  camera.lookAt(t); if (cam.roll) camera.rotateZ(cam.roll); camera.updateMatrixWorld(); req();
}
function viewSize() { return { w: view.clientWidth || 1, h: view.clientHeight || 1 }; }
function resize() {
  const { w, h } = viewSize();
  renderer.setSize(w, h, false);
  camera.aspect = w / h; camera.updateProjectionMatrix();
  const d = Math.min(window.devicePixelRatio || 1, 2);
  ovc.width = Math.round(w * d); ovc.height = Math.round(h * d); octx.setTransform(d, 0, 0, d, 0, 0);
  drawOverlay(); req();
}
new ResizeObserver(resize).observe(view);

/* ================= matcaps ================= */
const MATCAPS = [
  { name: 'Clay', c: [0.76, 0.62, 0.53] }, { name: 'Porcelain', c: [0.88, 0.87, 0.84] }, { name: 'Slate', c: [0.47, 0.54, 0.64] },
  { name: 'Jade', c: [0.4, 0.63, 0.52] }, { name: 'Wax', c: [0.7, 0.29, 0.25] }, { name: 'Bronze', c: [0.68, 0.52, 0.29] }, { name: 'Graphite', c: [0.31, 0.33, 0.36] },
];
(function buildMatcaps() {
  const s = 256;
  const L = new V3(-0.45, 0.62, 0.64).normalize(), H = L.clone().add(new V3(0, 0, 1)).normalize();
  for (const m of MATCAPS) {
    const cv = document.createElement('canvas'); cv.width = cv.height = s;
    const ctx = cv.getContext('2d'), im = ctx.createImageData(s, s), d = im.data;
    for (let j = 0; j < s; j++) for (let i = 0; i < s; i++) {
      const x = (i + 0.5) / s * 2 - 1, y = 1 - (j + 0.5) / s * 2;
      const r2 = Math.min(0.999, x * x + y * y), z = Math.sqrt(1 - r2);
      const nx = x / Math.sqrt(r2 + z * z), ny = y / Math.sqrt(r2 + z * z);
      const diff = Math.max(0, nx * L.x + ny * L.y + z * L.z);
      const amb = 0.26 + 0.16 * (ny * 0.5 + 0.5);
      const spec = Math.pow(Math.max(0, nx * H.x + ny * H.y + z * H.z), 38) * 0.32;
      const rim = Math.pow(1 - z, 2.6) * 0.22;
      const back = Math.max(0, nx * 0.6 - ny * 0.3) * 0.07;
      const o = (j * s + i) * 4, col = [0.78, 0.84, 0.95];
      for (let k = 0; k < 3; k++) d[o + k] = Math.max(0, Math.min(255, 255 * (m.c[k] * (amb + 0.86 * diff) + spec + rim * col[k] + back * col[k])));
      d[o + 3] = 255;
    }
    ctx.putImageData(im, 0, 0);
    m.url = cv.toDataURL();
    m.tex = new THREE.CanvasTexture(cv); m.tex.colorSpace = THREE.SRGBColorSpace;
  }
})();

